import {BRIDGES,SPLITS,exchange,fromNumber,value} from './model.js';
import {newMaterial,chunks,cutMaterial,moveMaterial,materialTotals} from './material.js';
const $ = selector => document.querySelector(selector);
const scene = $('#scene');
const media = matchMedia('(max-width:600px)');
const reduced = matchMedia('(prefers-reduced-motion: reduce)');
let mode='bridge', index=0, splitIndex=0, state=newMaterial(), bank=fromNumber(24), workshop={total:12,groups:[]};
let selected=null, history=[], complete=false, sound=false, drag=null, demoFrame=0, demoStart=0, demoActive=false, flash='', hint='';
let soundContext, introTimer;
const seenMaterials=new Set();
function intro(){if(mode==='workshop'||seenMaterials.has(mode))return;seenMaterials.add(mode);introTimer=setTimeout(demonstration,700);}
const displaySettings={theme:'soft',font:'round',size:'medium',dark:false};
try{Object.assign(displaySettings,JSON.parse(localStorage.getItem('zahlenwerkstatt-display')||'{}'));}catch{}
function applyDisplaySettings(){document.body.dataset.theme=displaySettings.theme;document.body.dataset.font=displaySettings.font;document.body.dataset.size=displaySettings.size;document.body.dataset.dark=displaySettings.dark?'true':'false';document.querySelectorAll('button[data-theme]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.theme===displaySettings.theme)));document.querySelectorAll('button[data-font]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.font===displaySettings.font)));document.querySelectorAll('button[data-size]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.size===displaySettings.size)));$('#dark-toggle').setAttribute('aria-pressed',String(displaySettings.dark));try{localStorage.setItem('zahlenwerkstatt-display',JSON.stringify(displaySettings));}catch{}}
function setDisplaySetting(key,value){displaySettings[key]=value;applyDisplaySettings();}
const taskNames={bridge:'Mach die Zehn voll.',split:'Mach zwei Teile.',bank:'Baue deine Zahl.',workshop:'Lege deine Pakete.'};
const defs=`<defs><radialGradient id="blue" cx="30%" cy="20%" r="95%"><stop stop-color="#e2f1f1"/><stop offset=".55" stop-color="#9ec7ce"/><stop offset="1" stop-color="#6899a7"/></radialGradient><radialGradient id="coral" cx="30%" cy="20%" r="95%"><stop stop-color="#fff0dc"/><stop offset=".55" stop-color="#e4b795"/><stop offset="1" stop-color="#ba8b71"/></radialGradient><radialGradient id="gold" cx="30%" cy="20%" r="95%"><stop stop-color="#fff4d4"/><stop offset=".55" stop-color="#e6cc91"/><stop offset="1" stop-color="#baa06c"/></radialGradient><filter id="shadow" x="-30%" y="-30%" width="160%" height="180%"><feDropShadow dx="2" dy="7" stdDeviation="6" flood-color="#324c43" flood-opacity=".12"/></filter></defs>`;
function layout(){return media.matches?{w:520,h:720,r:31,step:86,tx:88,ty:106,sy:478,sx:88,row:120,board:{x:20,y:38,w:480,h:325},source:{x:20,y:410,w:480,h:270},restY:290,cutY:55}:{w:920,h:450,r:25,step:65,tx:83,ty:132,sy:163,sx:544,row:98,board:{x:27,y:70,w:374,h:295},source:{x:481,y:84,w:398,h:267},restY:298,cutY:46};}
function pos(id,l=layout()){return {x:l.sx+(id%5)*l.step,y:l.sy+Math.floor(id/5)*l.row};}
function targetPos(id,which,l=layout()){return {x:l.tx+(id%5)*l.step,y:which==='rest'?l.restY+Math.floor(id/5)*70:l.ty+Math.floor(id/5)*(media.matches?80:69)};}
function bead(x,y,r,color='coral',extra=''){return `<g ${extra}><circle class="bead-circle" cx="${x}" cy="${y}" r="${r}" fill="url(#${color})" stroke="${color==='blue'?'#397fa6':color==='gold'?'#b1873c':'#b96740'}"/><ellipse class="bead-glint" cx="${x-r*.25}" cy="${y-r*.35}" rx="${r*.3}" ry="${r*.16}"/></g>`;}
function announce(text){$('#announcer').textContent=text;}
function speak(text){if(!sound||!('speechSynthesis' in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='de-DE';u.rate=.85;speechSynthesis.speak(u);}
function clickSound(){if(!sound)return;try{soundContext??=new (window.AudioContext||window.webkitAudioContext)();soundContext.resume();const osc=soundContext.createOscillator(),gain=soundContext.createGain();osc.connect(gain);gain.connect(soundContext.destination);osc.type='sine';osc.frequency.setValueAtTime(650,soundContext.currentTime);osc.frequency.exponentialRampToValueAtTime(380,soundContext.currentTime+.09);gain.gain.setValueAtTime(.045,soundContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,soundContext.currentTime+.12);osc.start();osc.stop(soundContext.currentTime+.13);}catch{}}
function remember(){history.push({state:structuredClone(state),bank:{...bank},workshop:structuredClone(workshop),complete});if(history.length>40)history.shift();}
function stopDemo(){clearTimeout(introTimer);cancelAnimationFrame(demoFrame);demoFrame=0;demoActive=false;$('#scene-wrap .demo-caption')?.remove();$('#demo-layer')?.remove();document.querySelectorAll('[data-demo-hide]').forEach(el=>{el.style.opacity='';el.removeAttribute('data-demo-hide');});}
function startMode(next){stopDemo();mode=next;selected=null;history=[];complete=false;hint='';state=mode==='split'?newMaterial(SPLITS[splitIndex][1],SPLITS[splitIndex][0],'split'):newMaterial(...BRIDGES[index]);if(mode==='workshop')workshop={total:12,groups:[]};render();intro();}
function restart(){if(mode==='bank'){remember();bank=fromNumber(0);hint='Nimm dir Perlen.';render();return;}if(mode==='workshop'){remember();workshop={total:workshop.total,groups:[]};complete=false;hint='Wähle ein Paket.';render();return;}startMode(mode);}
function instruction(){if(hint)return hint;if(mode==='bank')return 'Baue deine Zahl.';if(mode==='workshop')return workshop.groups.reduce((a,b)=>a+b,0)===workshop.total?'Alles passt!':'Lege Pakete auf die Matte.';if(complete)return 'Das passt!';if(state.phase==='answer')return mode==='bridge'?'Wie viel ist das zusammen?':'Wie viele blieben übrig?';if(state.phase==='rest')return 'Leg den Rest dazu.';if(selected)return 'Leg das Stück in die Lücke.';return taskNames[mode];}
function groupMarkup(ids,l,selectedId=false){const points=ids.map(i=>pos(i,l));let outline='';for(const row of [0,1]){const part=ids.filter(i=>Math.floor(i/5)===row);if(!part.length)continue;const first=pos(part[0],l),last=pos(part.at(-1),l);outline+=`<rect class="piece-outline" x="${first.x-l.r-7}" y="${first.y-l.r-6}" width="${last.x-first.x+2*l.r+14}" height="${2*l.r+12}" rx="${l.r+8}"/>`;}
 const middle=(points[0].x+points[Math.min(4,points.length-1)].x)/2;
 return `<g class="material ${selectedId?'selected':''} ${flash===String(ids[0])?'recoil':''}" data-chunk="${ids[0]}" tabindex="0" role="button" aria-label="${ids.length} Perlen greifen" aria-pressed="${selectedId}">${outline}${points.map((p,i)=>bead(p.x,p.y,l.r,'coral',`data-source-bead="${ids[i]}"`)).join('')}<g aria-hidden="true"><rect class="number-tag" x="${middle-21}" y="${points[0].y-l.r-42}" width="42" height="30" rx="11"/><text class="material-number" text-anchor="middle" x="${middle}" y="${points[0].y-l.r-19}">${ids.length}</text></g></g>`;
}
function cutControls(l){return Array.from({length:state.b-1},(_,i)=>i+1).map(n=>{const left=pos(n-1,l),right=pos(n,l);const sameRow=Math.floor((n-1)/5)===Math.floor(n/5);const x=sameRow?(left.x+right.x)/2:l.source.x+l.source.w-30,y=sameRow?left.y+l.cutY:left.y+48;const possible=chunks(state).some(ids=>ids.includes(n-1)&&ids.includes(n));if(!possible)return state.cuts.includes(n)?`<path class="cut-line" d="M ${sameRow?x:left.x+l.r+9} ${left.y-l.r-10} v ${2*l.r+18}"/>`:'';return `<g class="cut-control" data-cut="${n}" tabindex="0" role="button" aria-label="Nach ${n} Perlen teilen"><rect x="${x-(media.matches?32:27)}" y="${y-(media.matches?32:23)}" width="${media.matches?64:54}" height="${media.matches?64:46}" rx="16" fill="transparent"/><circle class="cut-handle" cx="${x}" cy="${y}" r="18"/><text class="cut-symbol" x="${x}" y="${y+8}" text-anchor="middle">✂</text></g>`;}).join('');}
function materialScene(){const l=layout(),base=mode==='bridge'?state.a:0,need=mode==='bridge'?10-state.a:state.a;const firstCount=mode==='bridge'?10:state.a;const showRest=state.phase!=='first';const restCount=state.b-need;let svg=defs;
 svg+=`<rect class="board" x="${l.board.x}" y="${l.board.y}" width="${l.board.w}" height="${l.board.h}" rx="28" filter="url(#shadow)"/><g class="drop-zone ${selected&&state.phase==='first'?'ready':''}" data-drop="first" role="button" tabindex="0" aria-label="Stück in ${need-state.first.length} freie Plätze legen"><rect x="${l.board.x+8}" y="${l.board.y+5}" width="${l.board.w-16}" height="${mode==='bridge'?190:150}" fill="transparent" rx="20"/>`;
 for(let i=0;i<firstCount;i++){const p=targetPos(i,'first',l),filled=i<base+state.first.length;svg+=filled?bead(p.x,p.y,l.r,i<base?'blue':'coral',`class="${flash==='first'?'settle':''}"`):`<circle class="empty-hole" cx="${p.x}" cy="${p.y}" r="${l.r}"/>`;}
 svg+=`</g><text class="board-number" x="${l.board.x+l.board.w/2}" y="${mode==='bridge'||firstCount>5?l.ty+(media.matches?141:124):l.ty+70}" text-anchor="middle">${base+state.first.length || ''}</text>`;
 if(showRest){svg+=`<path d="M ${l.board.x+25} ${l.restY-35} H ${l.board.x+l.board.w-25}" stroke="#d5c29b" stroke-width="2"/><g class="drop-zone ${selected&&state.phase==='rest'?'ready':''}" data-drop="rest" tabindex="0" role="button" aria-label="Den Rest auf die Matte legen"><rect x="${l.board.x+8}" y="${l.restY-42}" width="${l.board.w-16}" height="88" fill="transparent"/>`;for(let i=0;i<restCount;i++){const p=targetPos(i,'rest',l);svg+=i<state.rest.length?bead(p.x,p.y,l.r,'coral',`class="${flash==='rest'?'settle':''}"`):`<circle class="empty-hole" cx="${p.x}" cy="${p.y}" r="${l.r}"/>`;}svg+='</g>';}
 svg+=`<rect class="source-tray" x="${l.source.x}" y="${l.source.y}" width="${l.source.w}" height="${l.source.h}" rx="32" filter="url(#shadow)"/>`;
 for(let i=0;i<state.b;i++){const p=pos(i,l);svg+=`<circle class="${state.first.includes(i)||state.rest.includes(i)?'ghost-origin':'source-outline'}" cx="${p.x}" cy="${p.y}" r="${l.r}"/>`;}
 for(const ids of chunks(state))svg+=groupMarkup(ids,l,selected?.ids?.[0]===ids[0]);
 svg+=cutControls(l);
 const parts=state.cuts.length?[0,...state.cuts,state.b].slice(1).map((n,i)=>n-[0,...state.cuts][i]):[];
 svg+=`<text class="source-label" x="${l.source.x+l.source.w/2}" y="${l.source.y+l.source.h+34}" text-anchor="middle">${state.b}${parts.length?' = '+parts.join(' + '):''}</text>`;
 if(state.phase==='first'&&!state.cuts.length)svg+=`<g aria-hidden="true"><path class="connector" d="M ${l.source.x+l.source.w/2} ${l.source.y+l.source.h-24} v 13"/></g>`;
 return svg;
}
function bankLayout(){return media.matches?{w:520,h:695,board:{x:20,y:20,w:480,h:420},x:62,y:87,dx:225,dy:68,unit:18,r:8,actionY:466,supplyY:610}:{w:920,h:450,board:{x:25,y:20,w:630,h:385},x:75,y:80,dx:300,dy:62,unit:20,r:9,actionY:60,supplyY:305};}
function miniRod(x,y,step,r,filled=true){return `<rect x="${x-r-3}" y="${y-r-3}" width="${9*step+2*r+6}" height="${2*r+6}" rx="${r+3}" fill="${filled?'#e5b552':'none'}" stroke="#b38431" stroke-width="2"/>${Array.from({length:10},(_,i)=>bead(x+i*step,y,r,'gold')).join('')}`;}
function exchangeIcon(x,y,width,opening){const rodX=x+width/2-65,dotsX=x+width/2+26;const dots=(dx)=>Array.from({length:10},(_,i)=>bead(dx+(i%5)*10,y+(i<5?-6:6),4,'gold')).join('');return opening?miniRod(rodX,y,6,3)+`<text x="${x+width/2-4}" y="${y+8}" text-anchor="middle" font-size="25">→</text>`+dots(dotsX):dots(rodX)+`<text x="${x+width/2-4}" y="${y+8}" text-anchor="middle" font-size="25">→</text>`+miniRod(dotsX,y,6,3);}
function looseBeads(x,y,n,l){return Array.from({length:n},(_,i)=>bead(x+(i%5)*l.unit,y+(n>5?(i<5?-12:12):0),l.r,'gold')).join('');}
function bankScene(){const l=bankLayout();let svg=defs+`<g class="drop-zone" data-drop="bank" tabindex="0" role="button" aria-label="Perlen auf die Matte legen"><rect class="bank-zone" x="${l.board.x}" y="${l.board.y}" width="${l.board.w}" height="${l.board.h}" rx="27" filter="url(#shadow)"/></g>`;
 let packet=0;for(let i=0;i<bank.tens;i++,packet++){const x=l.x+(packet%2)*l.dx,y=l.y+Math.floor(packet/2)*l.dy;svg+=`<g class="bank-item" data-bank="rod" data-index="${i}" tabindex="0" role="button" aria-label="Zehner öffnen oder verschieben"><rect x="${x-16}" y="${y-24}" width="${l.unit*9+32}" height="48" rx="16" fill="transparent"/>${miniRod(x,y,l.unit,l.r)}</g>`;}
 for(let start=0;start<bank.units;start+=10,packet++){const n=Math.min(10,bank.units-start),x=l.x+(packet%2)*l.dx,y=l.y+Math.floor(packet/2)*l.dy;svg+=`<g class="bank-item" data-bank="units" data-count="${n}" tabindex="0" role="button" aria-label="${n} Einer ${n===10?'bündeln':'greifen'}"><rect x="${x-16}" y="${y-29}" width="${l.unit*Math.min(n-1,4)+32}" height="58" rx="16" fill="transparent"/>${looseBeads(x,y,n,l)}</g>`;}
 if(value(bank)===0)svg+=`<text class="bank-number" x="${l.board.x+l.board.w/2}" y="${l.board.y+l.board.h/2}" text-anchor="middle" opacity=".3">0</text>`;
 const ax=media.matches?22:693,ay=l.actionY,aw=media.matches?224:193,ah=media.matches?84:90;
 svg+=`<g class="bank-action ${bank.tens?'':'disabled'}" data-drop="open" data-bank-action="open" role="button" tabindex="0" aria-label="Einen Zehner in zehn Einer öffnen" aria-disabled="${!bank.tens}"><rect x="${ax}" y="${ay}" width="${aw}" height="${ah}" rx="21"/>${exchangeIcon(ax,ay+29,aw,true)}<text x="${ax+aw/2}" y="${ay+65}" text-anchor="middle" font-size="19">Öffnen</text></g>`;
 const bx=media.matches?274:ax,by=media.matches?ay:ay+111;
 svg+=`<g class="bank-action ${bank.units>=10?'':'disabled'}" data-drop="bundle" data-bank-action="bundle" role="button" tabindex="0" aria-label="Zehn Einer zu einem Zehner bündeln" aria-disabled="${bank.units<10}"><rect x="${bx}" y="${by}" width="${aw}" height="${ah}" rx="21"/>${exchangeIcon(bx,by+29,aw,false)}<text x="${bx+aw/2}" y="${by+65}" text-anchor="middle" font-size="19">Bündeln</text></g>`;
 const supplyX=media.matches?56:694,sy=l.supplyY;
 svg+=`<g class="supply-item" data-supply="1" role="button" tabindex="0" aria-label="Einen Einer dazu nehmen"><rect x="${supplyX-24}" y="${sy-26}" width="58" height="58" rx="17" fill="#d2ecea" stroke="#87b7b7" stroke-width="2"/>${bead(supplyX+5,sy+3,15,'gold')}<text x="${supplyX+5}" y="${sy+59}" text-anchor="middle" class="source-label">1</text></g>`;
 const rx=media.matches?180:778;svg+=`<g class="supply-item" data-supply="10" role="button" tabindex="0" aria-label="Einen Zehner dazu nehmen"><rect x="${rx-16}" y="${sy-26}" width="${media.matches?198:100}" height="58" rx="17" fill="#d2ecea" stroke="#87b7b7" stroke-width="2"/>${miniRod(rx,sy+3,media.matches?18:8,media.matches?8:4)}<text x="${rx+(media.matches?81:36)}" y="${sy+59}" text-anchor="middle" class="source-label">10</text></g>`;
 const trashX=media.matches?450:807,trashY=media.matches?sy+1:405;svg+=`<g class="bank-action" data-drop="trash" role="button" tabindex="0" aria-label="Ausgewähltes Material zurücklegen"><circle cx="${trashX}" cy="${trashY}" r="27" fill="#d2ecea" stroke="#87b7b7" stroke-width="2"/><text x="${trashX}" y="${trashY+9}" text-anchor="middle" font-size="29" style="fill:#486875">↩</text></g>`;
 return svg;
}
function workshopLayout(){const height=Math.max(320,Math.ceil(workshop.groups.length/2)*88+140);return media.matches?{w:520,h:height+325,board:{x:20,y:25,w:480,h:height},paletteY:height+65}:{w:920,h:Math.max(450,height+65),board:{x:27,y:32,w:580,h:height},paletteY:52};}
function workshopBeads(count,l,x,y,compact=false){const gap=compact?14:25,r=compact?5:10;return Array.from({length:count},(_,i)=>bead(x+(i%5)*gap,y+Math.floor(i/5)*(compact?15:26),r,'coral')).join('');}
function workshopPack(count,x,y,idx){const width=media.matches?210:252;return `<g class="workshop-pack" data-package-index="${idx}" tabindex="0" role="button" aria-label="${count}er-Paket entfernen"><rect class="package-card" x="${x-17}" y="${y-24}" width="${width}" height="72" rx="21"/><text class="package-count" x="${x+width-40}" y="${y+17}" text-anchor="end">${count}</text>${workshopBeads(count,workshopLayout(),x+8,y+1)}</g>`;}
function workshopScene(){const l=workshopLayout(),used=workshop.groups.reduce((a,b)=>a+b,0),left=l.board.x+36;let svg=defs+`<g data-drop="workshop-board"><rect class="workshop-board" x="${l.board.x}" y="${l.board.y}" width="${l.board.w}" height="${l.board.h}" rx="32" filter="url(#shadow)"/><text class="workshop-kicker" x="${l.board.x+27}" y="${l.board.y+37}">Meine Zahl</text><text class="workshop-total" x="${l.board.x+l.board.w-30}" y="${l.board.y+46}" text-anchor="end">${workshop.total}</text><text class="workshop-used" x="${l.board.x+27}" y="${l.board.y+l.board.h-25}">${used===workshop.total?'✓ Fertig':`${used} gelegt · ${workshop.total-used} frei`}</text>`;
 workshop.groups.forEach((count,i)=>{const x=left+(i%2)*(media.matches?232:278),y=l.board.y+102+Math.floor(i/2)*88;svg+=workshopPack(count,x,y,i);});svg+='</g>';
 const totals=[5,10,12,15,20];svg+=`<text class="workshop-label" x="${media.matches?30:641}" y="${l.paletteY+8}">Zahl</text>`;totals.forEach((n,i)=>{const x=media.matches?28+i*95:641+(i%3)*87,y=media.matches?l.paletteY+28:l.paletteY+28+Math.floor(i/3)*60;svg+=`<g class="workshop-total-choice ${n===workshop.total?'active':''}" data-workshop-total="${n}" tabindex="0" role="button" aria-label="Zahl ${n}"><rect x="${x}" y="${y}" width="${media.matches?84:75}" height="48" rx="16"/><text x="${x+(media.matches?42:37.5)}" y="${y+31}" text-anchor="middle">${n}</text></g>`;});
 const packages=[1,2,5,10];svg+=`<text class="workshop-label" x="${media.matches?30:641}" y="${media.matches?l.paletteY+119:l.paletteY+174}">Pakete</text>`;packages.forEach((n,i)=>{const x=media.matches?28+i*119:641+(i%2)*132,y=media.matches?l.paletteY+141:l.paletteY+195+Math.floor(i/2)*84;svg+=`<g class="package-choice" data-package-add="${n}" tabindex="0" role="button" aria-label="${n}er-Paket nehmen"><rect x="${x}" y="${y}" width="${media.matches?107:120}" height="70" rx="19"/>${workshopBeads(n,l,x+13,y+24,true)}<text x="${x+(media.matches?91:104)}" y="${y+53}" text-anchor="middle">${n}</text></g>`;});return svg;}
function resultNumber(){return mode==='bridge'?state.a+state.b:state.b-state.a;}
function workshopAdd(count){if(workshop.groups.reduce((a,b)=>a+b,0)+count>workshop.total){invalid('Das Paket ist zu groß.',count);return;}remember();workshop={...workshop,groups:[...workshop.groups,count]};hint='';complete=workshop.groups.reduce((a,b)=>a+b,0)===workshop.total;render();announce(`${count}er-Paket gelegt.`);}
function workshopSetTotal(n){remember();workshop={total:n,groups:[]};complete=false;hint='';render();announce(`Neue Zahl: ${n}.`);}
function workshopRemove(i){remember();workshop={...workshop,groups:workshop.groups.filter((_,idx)=>idx!==i)};complete=false;hint='';render();}
function render(){const l=mode==='bank'?bankLayout():mode==='workshop'?workshopLayout():layout();scene.setAttribute('viewBox',`0 0 ${l.w} ${l.h}`);scene.innerHTML=mode==='bank'?bankScene():mode==='workshop'?workshopScene():materialScene();$('#prompt').textContent=instruction();$('#equation').innerHTML=mode==='bank'?`<span>${value(bank)}</span> <span style="font-size:.55em;letter-spacing:0">= ${bank.tens*10} + ${bank.units}</span>`:mode==='workshop'?`<span>${workshop.total}</span> <span style="font-size:.55em;letter-spacing:0">= ${workshop.groups.length?workshop.groups.join(' + '):'?'}</span>`:mode==='split'?`<span class="b">${state.b}</span> = ${state.a} + ${state.phase==='answer'?`<span class="answer-socket" data-result="true">${complete?resultNumber():'?'}</span>`:'?'}`:`<span class="a">${state.a}</span> + <span class="b">${state.b}</span>${state.phase==='answer'?` = <span class="answer-socket" data-result="true">${complete?resultNumber():'?'}</span>`:''}`;
 document.querySelectorAll('[data-mode]').forEach(b=>{if(b.dataset.mode===mode)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#undo').disabled=!history.length;$('#next').hidden=!complete;$('#small-hint').textContent=mode==='bank'?(hint||'Perlen nehmen · Zehner tauschen'):mode==='workshop'?(hint||'Zahl wählen · Paket nehmen'):selected?'Greifen. Hinüberlegen.':state.phase==='first'&&!state.cuts.length?'✂ Teilen':state.phase==='rest'?'Der Rest gehört dazu.':'';
 if(mode!=='bank'&&mode!=='workshop'&&state.phase==='answer'&&!complete){const n=resultNumber(),options=[n-1,n,n+1],shift=(index+splitIndex)%3,ordered=[...options.slice(shift),...options.slice(0,shift)];$('#answer-area').innerHTML=`<div class="answers" role="group" aria-label="Passende Zahl auswählen">${ordered.map(x=>`<button class="number-tile" data-answer="${x}" aria-label="${x} als Antwort">${x}</button>`).join('')}</div>`;}else $('#answer-area').innerHTML=complete&&mode!=='workshop'?`<div class="success-mark"><span aria-hidden="true">✓</span><span>${mode==='bridge'?`10 + ${state.b-state.first.length} = ${resultNumber()}`:`${state.a} + ${state.b-state.a} = ${state.b}`}</span></div>`:'';
 $('#activity-label').textContent={bridge:'Zur Zehn',split:'Teilen',bank:'Bauen',workshop:'Freie Werkstatt'}[mode];
 $('#demo').hidden=mode==='workshop';$('#demo').disabled=mode!=='bank'&&state.phase==='answer';
 if(mode==='workshop'){$('#next').hidden=true;const used=workshop.groups.reduce((a,b)=>a+b,0);$('#equation').innerHTML=`<span>${workshop.total}</span><span style="font-size:.55em;letter-spacing:0">= ${workshop.groups.length?workshop.groups.join(' + ')+(used<workshop.total?' + …':''):'?'}</span>`;}
 flash='';
}
function doCut(n){stopDemo();const next=cutMaterial(state,n);if(next===state)return;remember();state=next;selected=null;hint='';clickSound();render();announce(`${state.b} geteilt. ${chunks(state).map(g=>g.length).join(' und ')}.`);}
function invalid(text,which){hint=text;flash=String(which??'');render();announce(text);speak(text);}
function doMove(ids,dest){stopDemo();const next=moveMaterial(state,ids,dest);if(next===state){invalid(ids.length>(state.mode==='bridge'?10-state.a:state.a)-state.first.length&&state.phase==='first'?'Das Stück ist zu groß. Teile es.':'Lege das Stück in die freien Plätze.',ids[0]);return false;}remember();state=next;selected=null;hint='';flash=dest;clickSound();render();announce(instruction());speak(instruction());return true;}
function bankAction(action,material){stopDemo();let next=bank;
 if(action==='bank'&&material?.type==='supply'){if(value(bank)+material.count>100){invalid('Bis 100 ist Platz.');return;}next={...bank,[material.count===10?'tens':'units']:bank[material.count===10?'tens':'units']+1};}
 else if(action==='open'&&(!material||material.type==='rod'))next=exchange(bank,'open');
 else if(action==='bundle'&&(!material||material.type==='units'))next=exchange(bank,'bundle');
 else if(action==='trash'&&material?.type==='rod'&&bank.tens)next={...bank,tens:bank.tens-1};
 else if(action==='trash'&&material?.type==='units'&&bank.units>=material.count)next={...bank,units:bank.units-material.count};
 if(next===bank){if(material)invalid('Probier die andere Ablage.');return;}remember();bank=next;selected=null;hint='';clickSound();render();announce(`${bank.tens} Zehner und ${bank.units} Einer. Zusammen ${value(bank)}.`);
}
function chooseAnswer(n){if(mode==='bank'||state.phase!=='answer'||complete)return;if(n!==resultNumber()){const text=mode==='bridge'?`Eine Zehn und ${state.rest.length}.`:`${state.rest.length} sind übrig.`;hint=text;$('#prompt').textContent=text;document.querySelector(`[data-answer="${n}"]`)?.classList.add('recoil');announce(text);speak(text);return;}remember();complete=true;hint='';clickSound();render();announce('Das passt.');speak('Das passt!');$('#next').focus({preventScroll:true});}
function point(event){const p=new DOMPoint(event.clientX,event.clientY);return p.matrixTransform(scene.getScreenCTM().inverse());}
function sourceFrom(element){if(element.hasAttribute('data-chunk'))return {type:'chunk',ids:chunks(state).find(c=>c[0]===Number(element.dataset.chunk))};if(element.hasAttribute('data-cut'))return {type:'cut',n:Number(element.dataset.cut)};if(element.hasAttribute('data-supply'))return {type:'supply',count:Number(element.dataset.supply)};if(element.hasAttribute('data-bank'))return {type:element.dataset.bank,count:Number(element.dataset.count||10)};if(element.hasAttribute('data-package-add'))return {type:'package-add',count:Number(element.dataset.packageAdd)};if(element.hasAttribute('data-package-index'))return {type:'package',index:Number(element.dataset.packageIndex)};if(element.hasAttribute('data-workshop-total'))return {type:'workshop-total',total:Number(element.dataset.workshopTotal)};return null;}
function focusSelection(){if(selected?.type==='chunk')scene.querySelector(`[data-chunk="${selected.ids[0]}"]`)?.focus();}
function tap(element){const source=sourceFrom(element);if(source?.type==='cut'){doCut(source.n);return;}if(source?.type==='chunk'){selected=selected?.ids?.[0]===source.ids[0]?null:source;hint='';render();focusSelection();return;}if(source?.type==='supply'){bankAction('bank',source);return;}if(source?.type==='rod'){bankAction('open',source);return;}if(source?.type==='units'){if(source.count===10)bankAction('bundle',source);else{selected=source;hint='Lege die Einer zurück oder nimm mehr.';render();}return;}
 if(element.hasAttribute('data-bank-action')){bankAction(element.dataset.bankAction);return;}
 if(source?.type==='package-add'){workshopAdd(source.count);return;}if(source?.type==='package'){workshopRemove(source.index);return;}if(source?.type==='workshop-total'){workshopSetTotal(source.total);return;}
 if(element.hasAttribute('data-drop')){const dest=element.dataset.drop;if(mode==='bank')bankAction(dest,selected);else if(selected?.type==='chunk')doMove(selected.ids,dest);else{hint='Nimm zuerst ein Perlenstück.';render();}}
}
const interact='[data-chunk],[data-cut],[data-supply],[data-bank],[data-bank-action],[data-drop],[data-package-add],[data-package-index],[data-workshop-total]';
scene.addEventListener('pointerdown',e=>{if(e.button!==0)return;const el=e.target.closest(interact);if(!el)return;stopDemo();const source=sourceFrom(el);const p=point(e);drag={el,source,pointer:e.pointerId,start:p,x:p.x,y:p.y,active:false,ghost:null};scene.setPointerCapture(e.pointerId);if(source)e.preventDefault();});
scene.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;const p=point(e);if(!drag.active&&drag.source&&Math.hypot(p.x-drag.start.x,p.y-drag.start.y)>8){drag.active=true;const ghost=drag.el.cloneNode(true);ghost.removeAttribute('data-chunk');ghost.removeAttribute('data-cut');ghost.removeAttribute('tabindex');ghost.setAttribute('aria-hidden','true');ghost.style.pointerEvents='none';ghost.id='drag-ghost';ghost.classList.add('demo-ghost');drag.el.style.opacity='.25';scene.append(ghost);drag.ghost=ghost;}
 if(drag.active){e.preventDefault();drag.x=p.x;drag.y=p.y;drag.ghost.setAttribute('transform',`translate(${p.x-drag.start.x} ${p.y-drag.start.y})`);scene.querySelectorAll('.hover').forEach(el=>el.classList.remove('hover'));document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]')?.classList.add('hover');}
});
function nearestCut(p){const l=layout();let best=null,distance=Infinity;for(let i=1;i<state.b;i++){const a=pos(i-1,l),b=pos(i,l);if(Math.floor((i-1)/5)!==Math.floor(i/5))continue;const d=Math.hypot(p.x-(a.x+b.x)/2,p.y-a.y);if(d<distance){best=i;distance=d;}}return distance<105?best:null;}
scene.addEventListener('pointerup',e=>{if(!drag||drag.pointer!==e.pointerId)return;const current=drag;drag=null;current.ghost?.remove();current.el.style.opacity='';scene.querySelectorAll('.hover').forEach(el=>el.classList.remove('hover'));if(!current.active){tap(current.el);return;}let dest=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]')?.dataset.drop;if(mode==='bank'&&!dest){const p=point(e),b=bankLayout().board;if(p.x>=b.x&&p.x<=b.x+b.w&&p.y>=b.y&&p.y<=b.y+b.h)dest='bank';}if(current.source.type==='cut'){const n=nearestCut(point(e));if(n)doCut(n);else doCut(current.source.n);}else if(mode==='workshop'&&current.source.type==='package-add'&&dest==='workshop-board')workshopAdd(current.source.count);else if(current.source.type==='chunk'&&dest)doMove(current.source.ids,dest);else if(mode==='bank'&&dest)bankAction(dest,current.source);else{hint='';render();}});
scene.addEventListener('pointercancel',()=>{drag?.ghost?.remove();if(drag)drag.el.style.opacity='';drag=null;scene.querySelectorAll('.hover').forEach(el=>el.classList.remove('hover'));});
scene.addEventListener('keydown',e=>{if(!['Enter',' '].includes(e.key))return;const el=e.target.closest(interact);if(!el)return;e.preventDefault();stopDemo();tap(el);});
let numberDrag=null;
document.addEventListener('pointerdown',e=>{const tile=e.target.closest('[data-answer]');if(!tile)return;stopDemo();numberDrag={n:Number(tile.dataset.answer),x:e.clientX,y:e.clientY,pointer:e.pointerId,ghost:null};tile.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!numberDrag||numberDrag.pointer!==e.pointerId)return;if(!numberDrag.ghost&&Math.hypot(e.clientX-numberDrag.x,e.clientY-numberDrag.y)>8){const ghost=document.createElement('div');ghost.className='number-tile';ghost.textContent=numberDrag.n;Object.assign(ghost.style,{position:'fixed',pointerEvents:'none',zIndex:50,transform:'translate(-50%,-50%)',display:'grid',placeItems:'center'});document.body.append(ghost);numberDrag.ghost=ghost;}if(numberDrag.ghost){e.preventDefault();numberDrag.ghost.style.left=e.clientX+'px';numberDrag.ghost.style.top=e.clientY+'px';}},{passive:false});
document.addEventListener('pointerup',e=>{if(!numberDrag||numberDrag.pointer!==e.pointerId)return;const d=numberDrag;numberDrag=null;d.ghost?.remove();if(!d.ghost||document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-result]'))chooseAnswer(d.n);});
document.addEventListener('pointercancel',()=>{numberDrag?.ghost?.remove();numberDrag=null;});
$('#answer-area').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('[data-answer]')){e.preventDefault();chooseAnswer(Number(e.target.dataset.answer));}});
