function bankDemonstration(){render();demoActive=true;const l=bankLayout(),opening=bank.tens>0;const source=scene.querySelector(opening?'[data-bank="rod"]':'[data-supply="10"]');const x=opening?l.x:media.matches?180:778,y=opening?l.y:l.supplyY+3,step=opening?l.unit:media.matches?18:8,r=opening?l.r:media.matches?8:4;source.dataset.demoHide='';source.style.opacity='0';const layer=document.createElementNS('http://www.w3.org/2000/svg','g');layer.id='demo-layer';layer.style.pointerEvents='none';layer.setAttribute('aria-hidden','true');scene.append(layer);const targetX=opening?(media.matches?50:716):l.x,targetY=opening?l.actionY+28:l.y;demoStart=performance.now();const run=now=>{if(!demoActive)return;const t=(now-demoStart)/1000,progress=Math.min(1,Math.max(0,(t-.4)/1.5)),p=reduced.matches?(progress>.5?1:0):progress*progress*(3-2*progress);let html='';if(opening&&t>2.2){html=looseBeads(x,y,10,l);}else{html=miniRod(x+(targetX-x)*p,y+(targetY-y)*p,step,r)+`<text class="demo-hand" x="${x+(targetX-x)*p+35}" y="${y+(targetY-y)*p+47}">☝</text>`;}layer.innerHTML=html;if(t>3.7){stopDemo();hint='Jetzt du!';$('#prompt').textContent=hint;return;}demoFrame=requestAnimationFrame(run);};demoFrame=requestAnimationFrame(run);}
function demonstration(){stopDemo();if(mode==='bank'){bankDemonstration();return;}if(state.phase==='answer')return;demoActive=true;selected=null;hint='';render();const caption=document.createElement('div');caption.className='demo-caption';caption.textContent='Schau mal …';$('#scene-wrap').append(caption);const l=layout(),needed=state.phase==='rest'?state.b-state.first.length:(mode==='bridge'?10-state.a:state.a)-state.first.length;const available=Array.from({length:state.b},(_,i)=>i).filter(i=>!state.first.includes(i)&&!state.rest.includes(i));const ids=available.slice(0,needed);const first=pos(ids[0],l),destination=targetPos((mode==='bridge'&&state.phase==='first'?state.a:0)+(state.phase==='first'?state.first.length:state.rest.length),state.phase,l);const layer=document.createElementNS('http://www.w3.org/2000/svg','g');layer.id='demo-layer';layer.setAttribute('aria-hidden','true');layer.style.pointerEvents='none';scene.append(layer);demoStart=performance.now();
 const run=now=>{if(!demoActive)return;const t=(now-demoStart)/1000;const travel=reduced.matches?(t>1?1:0):Math.max(0,Math.min(1,(t-1.2)/1.4));const eased=travel*travel*(3-2*travel);const dx=(destination.x-first.x)*eased,dy=(destination.y-first.y)*eased;let html='';
 if(t<1.2&&state.phase==='first'){const n=ids.at(-1)+1,p=pos(Math.max(0,n-1),l);html=`<circle cx="${p.x+l.step/2}" cy="${p.y+l.cutY}" r="27" fill="none" stroke="#fff2c8" stroke-width="4"/><text class="demo-hand" x="${p.x+l.step/2-7}" y="${p.y+l.cutY+49}">☝</text>`;}
 else{ids.forEach(id=>{const el=scene.querySelector(`[data-source-bead="${id}"]`);if(el){el.dataset.demoHide='';el.style.opacity='0';}});html=`<g class="demo-ghost">${ids.map((id,i)=>{const p=pos(id,l),target=targetPos((mode==='bridge'&&state.phase==='first'?state.a:0)+(state.phase==='first'?state.first.length:state.rest.length)+i,state.phase,l);return bead(p.x+(target.x-p.x)*eased,p.y+(target.y-p.y)*eased,l.r);}).join('')}<text class="demo-hand" x="${first.x+dx+8}" y="${first.y+dy+52}">☝</text></g>`;}
 layer.innerHTML=html;if(t>3.5){stopDemo();hint='Jetzt du!';$('#prompt').textContent=hint;return;}demoFrame=requestAnimationFrame(run);};demoFrame=requestAnimationFrame(run);
}
